-- Idempotent PostgreSQL schema for the DMERS shared operational database.
CREATE TABLE IF NOT EXISTS roles (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'responder' REFERENCES roles(name), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK (role IN ('admin','official','responder','volunteer','citizen')));
CREATE TABLE IF NOT EXISTS locations (id BIGSERIAL PRIMARY KEY, label TEXT NOT NULL, latitude NUMERIC CHECK(latitude BETWEEN -90 AND 90), longitude NUMERIC CHECK(longitude BETWEEN -180 AND 180), address TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incidents (id BIGSERIAL PRIMARY KEY, reference TEXT NOT NULL UNIQUE, disaster_type TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN ('low','moderate','high','critical')), status TEXT NOT NULL DEFAULT 'reported' CHECK(status IN ('reported','verified','dispatched','resolved','closed')), description TEXT NOT NULL, location_id BIGINT NOT NULL REFERENCES locations(id), reported_by BIGINT REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rescue_teams (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, capability TEXT NOT NULL, availability TEXT NOT NULL DEFAULT 'available' CHECK(availability IN ('available','deployed','unavailable')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hospitals (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL UNIQUE, location_id BIGINT REFERENCES locations(id), total_beds INTEGER NOT NULL DEFAULT 0 CHECK(total_beds >= 0), available_beds INTEGER NOT NULL DEFAULT 0 CHECK(available_beds BETWEEN 0 AND total_beds), status TEXT NOT NULL DEFAULT 'accepting' CHECK(status IN ('accepting','limited','divert')), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS partner_profiles (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, portal TEXT NOT NULL CHECK(portal IN ('ngo','dispatch','hospital')), institution TEXT NOT NULL, hospital_id BIGINT REFERENCES hospitals(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK((portal = 'hospital' AND hospital_id IS NOT NULL) OR (portal <> 'hospital' AND hospital_id IS NULL)));
CREATE TABLE IF NOT EXISTS missions (id BIGSERIAL PRIMARY KEY, incident_id BIGINT REFERENCES incidents(id), report_id TEXT, team_name TEXT, team_id BIGINT REFERENCES rescue_teams(id), hospital_id BIGINT REFERENCES hospitals(id), status TEXT NOT NULL DEFAULT 'assigned' CHECK(status IN ('assigned','acknowledged','en_route','on_scene','in_progress','at_hospital','completed','escalated','aborted')), assigned_by BIGINT REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE missions ADD COLUMN IF NOT EXISTS report_id TEXT;
ALTER TABLE missions ADD COLUMN IF NOT EXISTS team_name TEXT;
CREATE TABLE IF NOT EXISTS simulations (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, scenario TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), user_id BIGINT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_entries (id BIGSERIAL PRIMARY KEY, actor_id BIGINT REFERENCES users(id), action TEXT NOT NULL, subject TEXT NOT NULL, details TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_incidents_status ON incidents(status);
CREATE INDEX IF NOT EXISTS idx_incidents_severity ON incidents(severity);
CREATE INDEX IF NOT EXISTS idx_incidents_created ON incidents(created_at);
CREATE INDEX IF NOT EXISTS idx_missions_status ON missions(status);
CREATE INDEX IF NOT EXISTS idx_missions_incident ON missions(incident_id);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_entries(created_at);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_mission_per_incident ON missions(incident_id) WHERE incident_id IS NOT NULL AND status NOT IN ('completed','aborted');
CREATE UNIQUE INDEX IF NOT EXISTS one_active_mission_per_report ON missions(report_id) WHERE report_id IS NOT NULL AND status NOT IN ('completed','aborted');
